\label{LaplPol_exer}
Show that in the polar coordinates $(r,\theta)$ on $\mathbb R^2$,
\BE{LaplPol_e}\Delta\phi=\phi_{rr}+r^{-1}\phi_r+r^{-2}\phi_{\theta\theta}\,.\end{equation}

\label{Lapl_lmm1}
If $\phi\!:\ov{B_R}\!\longrightarrow\!\mathbb R$ is $C^2$, then
\BE{Lapl_e1}
2\pi R\,\phi(0)=-R\int_{(r,\theta)\in B_R}\!\!(\ln R\!-\!\ln r)\Delta\phi
+\int_{\partial B_R}\phi\,.\end{equation}

\label{Lapl_crl}
If $\phi\!:\ov{B_R}\!\longrightarrow\!\mathbb R$ is $C^2$ and $\Delta\phi\!\ge\!-C$ for some $C\!\in\!\mathbb R^+$, 
then
\BE{Lapl_e2}
\phi(0)\le \frac18 CR^2+\frac1{\pi R^2}\int_{B_R}\phi\,.\end{equation}

\label{Lapl_prp}
If $\phi\!:B_R\!\longrightarrow\!\mathbb R^{\ge0}$ is $C^2$ and 
there exists $A\!\in\!\mathbb R^+$ such that 
$\Delta\phi\!\ge\!-A\phi^2$ and $\displaystyle\int_{B_R}\phi<\frac{\pi}{8A}$, then
\BE{Lapl_e3}
\phi(0)\le \frac8{\pi R^2}\int_{B_R}\phi\,.\end{equation}

Let $z\!=\!s\!+\!\mathfrak i t$ be the standard coordinate on~$\mathbb{C}$. 
Denote by~$u_s$ and~$u_t$ the $s$ and $t$-partials of~$u$, respectively.
Since $u$ is $J$-holomorphic, i.e.~$u_s\!=\!-Ju_t$, and $g$ is $J$-compatible,
i.e.~$g(J\cdot,J\cdot)\!=\!g(\cdot,\cdot)$, $|u_s|_g^2\!=\!|u_t|_g^2$.
Since the Levi-Civita connection~$\nabla$ of~$g$ is $g$-compatible and torsion-free,
\BE{LapEng_e1}
\frac12 \frac{\textnormal{d}^2}{\textnormal{d}^2 t}|u_s|_g^2= |\nabla_tu_s|_g^2+\blr{\nabla_t\nabla_tu_s,u_t}_{\!g}
=|\nabla_tu_s|_g^2+\blr{\nabla_t\nabla_su_t,u_s}_{\!g}\,.\end{equation}
Similarly,
\BE{LapEng_e2}
\frac12 \frac{\textnormal{d}^2}{\textnormal{d}^2 s}|u_t|_g^2
=\big|\nabla_su_t\big|_g^2+\blr{\nabla_s\nabla_t u_s,u_t}_{\!g}.\end{equation}
Since $u_s\!=\!-Ju_t$, 
\BE{LapEng_e3}\begin{split}
\lr{\nabla_s\nabla_t u_s,u_t}_{\!g}&=-\blr{\nabla_s\nabla_t (Ju_t),u_t}_{\!g}\\
&=-\blr{J\nabla_s\nabla_t u_t,u_t}_{\!g} -\blr{(\nabla_sJ)\nabla_t u_t,u_t}_{\!g}
-\blr{\nabla_s((\nabla_tJ)u_t),u_t}_{\!g}\\
&=-\blr{\nabla_s\nabla_t u_t,u_s}_{\!g} -\blr{(\nabla_sJ)\nabla_t u_t,u_t}_{\!g}
-\blr{\nabla_s((\nabla_tJ)u_t),u_t}_{\!g}\,.
\end{split}\end{equation}
Putting (\ref{LapEng_e1})-(\ref{LapEng_e3}), we find that 
\BE{LapEng_e4}\begin{split}
\frac12\Delta\phi = \big|\nabla_tu_s\big|_g^2+\big|\nabla_su_t\big|_g^2+ 
\blr{R_g(u_t,u_s)u_t,u_s}_{\!g}
-\blr{(\nabla_sJ)\nabla_t u_t,u_t}_{\!g} -\blr{\nabla_s((\nabla_tJ)u_t),u_t}_{\!g}\,,
\end{split}\end{equation}
where $R_g$ is the curvature tensor of the connection~$\nabla$.
Since $u(\Omega)\!\subset\!B_r^g(x)$,
\BE{LapEng_e5}\begin{aligned}
\big|\lr{R_g(u_t,u_s)u_t,u_s}_g\big|&\le C_g(x,r)|u_s|_g^2|u_t|_g^2\,,\\
\big|\lr{(\nabla_sJ)\nabla_t u_t,u_t}_g\big|&\le  C_{J,g}(x,r)|u_s|_g|u_t|_g\big|\nabla_t(Ju_s)\big|_g 
\le C_{J,g}(x,r)|u_s|_g|u_t|_g\big(|u_s|_g|u_t|_g\!+\!|\nabla_tu_s|_g\big)\\
&\le (C_{J,g}(x,r)\!+\!C_{J,g}(x,r)^2)|u_s|_g^2|u_t|_g^2+|\nabla_tu_s|_g^2\,,\\
\big|\lr{\nabla_s((\nabla_tJ)u_t),u_t}_g\big|
&\le C_{J,g}(x,r)|u_t|_g^2\big(|u_s|_g|u_t|_g\!+\!|\nabla_su_t|_g\big)\\
&\le C_{J,g}(x,r)|u_s|_g|u_t|_g^3+C_{J,g}(x,r)^2|u_t|_g^4+|\nabla_su_t|_g^2.
\end{aligned}\end{equation}
Combining~(\ref{LapEng_e4}) and~(\ref{LapEng_e5}), we find that 
$$\frac12\Delta\phi \ge -C(x,r)\big(|u_s|_g^2|u_t|_g^2\!+\!|u_s|_g|u_t|_g^3\!+\!|u_t|_g^4\big)
\ge -3C(x,r)\phi^2,$$
as claimed.

\label{JHolomreg_lmm}
Let $(X,J,g)$, $R$, and $u$ be as in Proposition~\ref{JHolomreg_prp} and 
$$\gamma_r\!:S^1\longrightarrow X,\quad \gamma_r\big(\textnormal{e}^{\mathfrak i\theta}\big)=u\big(r\textnormal{e}^{\mathfrak i\theta}\big)
\qquad\forall\,r\!\in\!(0,R).$$
There exist $\delta\!\in\!(0,R)$ and $C\!\in\!\mathbb R^+$ such that 
\BE{JHolomreg1_e}E_g\big(u;B_r^*\big)\le C\ell_g(\gamma_r)^2 \qquad\forall\,r\!\in\!(0,\delta).\end{equation}

 Let $\exp$ be as above the statement of Lemma~\ref{distder_lmm},
$\delta_g$ and $\omega_x$
be as in the first two sentences in the proof of Proposition~\ref{MonotLmm_prp},
$$x_0=u(0), \quad \delta_0=\delta_g(x_0), \quad \omega_0=\omega_{x_0}, \qquad
E\!:(0,R)\longrightarrow \mathbb R, ~~ E(r)\!=\!E_g(u;B_r^*).$$
We can assume that the metric~$g$ is determined by~$J$ and~$\omega_0$ 
on $B_{\delta_0}^g(x_0)$.\\

\noindent
For a smooth loop $\gamma\!:S^1\!\longrightarrow\!B_{\delta_0}^g(x_0)$, define
\begin{gather*}
\xi_{\gamma}\!: S^1\longrightarrow T_{x_0}X \qquad\hbox{by}\quad
\exp_{x_0}\xi_{\gamma}\!\big(\textnormal{e}^{\mathfrak i\theta}\big)=\gamma\big(\textnormal{e}^{\mathfrak i\theta}\big),
~~\big|\xi_{\gamma}\!(\textnormal{e}^{\mathfrak i\theta})\big|<\delta_0,\\
f_{\gamma}\!: B_1\longrightarrow X, \qquad f_{\gamma}\big(r\textnormal{e}^{\mathfrak i\theta}\big)=
\exp_{x_0}\!\!\big(r\xi_{\gamma}(\textnormal{e}^{\mathfrak i\theta})\!\big).
\end{gather*}
In particular,
\begin{gather*}
\big|\partial_rf_{\gamma}(\rho\textnormal{e}^{\mathfrak i\theta})\big|_g
=\big|\xi_{\gamma}(\textnormal{e}^{\mathfrak i\theta})\big|_g\le\ell_g(\gamma)/2,\quad
\big|r^{-1}\partial_{\theta}f_{\gamma}(r\textnormal{e}^{\mathfrak i\theta})\big|_g
=\big|\textnormal{d}_{r\xi_{\gamma}(\textnormal{e}^{\mathfrak i\theta})}(\xi_{\gamma}'(\theta))\big|_g\le C\big|\gamma'(\theta)\big|_g
\end{gather*}
for some $C\!\in\!\mathbb R^+$ determined by~$x_0$.
Thus,
\BE{JHolomreg1_e3}\begin{split}
\bigg|\int_{B_1}\!f_{\gamma}^*\omega_0\bigg|
&\le C\!\!\int_0^{2\pi}\!\!\!\!\int_0^1
\big|\partial_rf_{\gamma}(\rho\textnormal{e}^{\mathfrak i\theta})\big|_g
\big|r^{-1}\partial_{\theta}f_{\gamma}(r\textnormal{e}^{\mathfrak i\theta})\big|_g r\,\textnormal{d} r\textnormal{d}\theta\\
&\le C'\ell_g(\gamma)\!\!\int_0^{2\pi}\!\!\!\!\int_0^r\!\!\big|\gamma'(\theta)\big|_gr\,\textnormal{d} r\textnormal{d}\theta
=\frac12 C'\ell_g(\gamma)^2
\end{split}\end{equation}
for some $C,C'\!\in\!\mathbb R^+$ determined by~$x_0$ and~$\omega_0$.\\

