\label{EnerPres2_crl}
If $(X,J)$ is a compact almost complex manifold with a Riemannian metric~$g$, 
then there exists $\hbar_{J,g}\!\in\!\mathbb R^+$ with the following properties.
If $u_i\!:B_1\!\longrightarrow\!X$ is a sequence of $J$-holomorphic maps converging
uniformly in the $C^{\infty}$-topology on compact subsets of~$B_1^*$
to a $J$-holomorphic map $u\!:B_1\!\longrightarrow\!X$ such that 
$$\lim_{i\longrightarrow\infty}\max_{\ov{B_{1/2}}}\big|\textnormal{d} u_i\big|_g=\infty$$
and the limit~(\ref{fmdfn_e}) exists, then 
\begin{enumerate}[label=(\arabic*),leftmargin=*]

\item\label{fmLowBnd_it} $\mathfrak m\ge\hbar_{J,g}$;

\item\label{noLoss_it} for every sequence $z_i\!\in\!B_{\delta}$ converging to~0 and
$\mu\!\in\!(\mathfrak m\!-\!\hbar_{J,g},\mathfrak m)$, 
the numbers \hbox{$\delta_i(\mu)\!\in\!(0,1\!-\!|z_i|)$} of Lemma~\ref{EnerPres1_lmm}\ref{dela_it} 
satisfy
\begin{gather}
\label{noEloss_e1} 
\lim_{R\longrightarrow\infty}\lim_{i\longrightarrow\infty}E_g(u_i;B_{R\delta_i(\mu)}(z_i))=\mathfrak m,\\
\label{noEloss_e2} 
\lim_{R\longrightarrow\infty}\lim_{\delta\longrightarrow0}
\lim_{i\longrightarrow\infty} \textnormal{diam}_g\big(u_i(B_{\delta}(z_i)\!-\!B_{R\delta_i(\mu)}(z_i))\big)=0.
\end{gather}

\end{enumerate}

Let $\hbar_{J,g}$ be the smaller of the constants~$\hbar_{J,g}$ 
in Corollaries~\ref{LowEner_crl} and~\ref{CylEner_crl}.
Let $u_i$, $u$, and~$\mathfrak m$ be as in the statement of the corollary.\\

\noindent
\ref{fmLowBnd_it} For each $i\!\in\!{\mathbb Z}^+$, let 
$$M_i=\max_{\ov{B_{1/2}}}\big|\textnormal{d}_zu_i\big|_g\in\mathbb R^+$$
and $z_i\!\in\!\ov{B_{1/2}}$ be such that $|\textnormal{d}_{z_i}u_i|_g\!=\!M_i$.
Since $M_i\!\longrightarrow\!\infty$ as $i\!\longrightarrow\!\infty$ and
$u_i$ converges uniformly in the $C^{\infty}$-topology on compact subsets of~$B_1^*$
to~$u$, $z_i\!\longrightarrow\!0$.
For $i\!\in\!{\mathbb Z}^+$ such that $|z_i|\!+\!1/\sqrt{M_i}\!<\!1/2$, define
$$v_i\!:B_{\sqrt{M_i}}\longrightarrow X, \qquad v_i(z)=u_i\big(z_i\!+\!z/M_i\big).$$
Thus, $v_i$ is a $J$-holomorphic map with 
\BE{EnerPres2_e3}\sup\big|\textnormal{d} v_i\big|_g=\big|\textnormal{d}_0v_i\big|_g=1, \qquad 
E_g(v_i)=E_g\big(u_i;B_{1/\sqrt{M_i}}(z_i)\big)\le 
E_g\big(u_i;B_{|z_i|+1/\sqrt{M_i}}\big)\,.\end{equation}
By the first statement in~(\ref{EnerPres2_e3}) and the ellipticity of the $\bar\partial$-operator, 
a subsequence of~$v_i$ converges  uniformly in the $C^{\infty}$-topology on compact subsets of~$\mathbb{C}$
to a non-constant $J$-holomorphic map \hbox{$v\!:\mathbb{C}\!\longrightarrow\!X$}.
By the second statement in~(\ref{EnerPres2_e3}) and Lemma~\ref{EnerPres1_lmm}\ref{deEner_it},
\BE{EnerPres2_e5} E_g(v)
\le \limsup_{i\longrightarrow\infty}E_g\big(u_i;B_{1/\sqrt{M_i}}(z_i)\big)
\le \lim_{\delta\longrightarrow0}\lim_{i\longrightarrow\infty}E_g\big(u_i;B_{\delta}\big)=\mathfrak m.\end{equation}
By Proposition~\ref{RemSing_prp}, $v$ thus extends to a $J$-holomorphic map 
$\wt{v}\!:\mathbb{P}^1\!\longrightarrow\!X$.
By Corollary~\ref{LowEner_crl}, 
$$E_g(v)=E_g(\wt{v})\ge \hbar_{J,g}\,.$$
Combining this with~(\ref{EnerPres2_e5}), we obtain the first claim.\\

\noindent
\ref{noLoss_it} By the first two statements in Lemma~\ref{EnerPres1_lmm}
and~(\ref{fmdfn_e}),
\BE{noLoss_e2} \lim_{\delta\longrightarrow0}\lim_{i\longrightarrow\infty}E_g\big(u_i;B_{\delta}(z_i)\big)=
\lim_{\delta\longrightarrow0}\mathfrak m(\delta)=\mathfrak m.\end{equation}
After passing to a subsequence of~$u_i$, we can thus assume that there exists
a sequence $\delta_i\!\longrightarrow\!0$ such~that
\BE{noLoss_e3} \lim_{i\longrightarrow\infty}E_g(u_i;B_{\delta_i}(z_i))=\mathfrak m.\end{equation}
Since $\delta_i\!\longrightarrow\!0$, (\ref{noLoss_e2}) and (\ref{noLoss_e3}) imply that 
\BE{noLoss_e5}\lim_{R\longrightarrow\infty}\lim_{i\longrightarrow\infty}E_g(u_i;B_{R\delta_i}(z_i))=\mathfrak m.\end{equation}

\vspace{.1in}

\noindent
Suppose $\mu\!\in\!(\mathfrak m\!-\!\hbar_{J,g},\mathfrak m)$.
By (\ref{noLoss_e5}) and the definition of~$\delta_i(\mu)$, 
$$ \lim_{R\longrightarrow\infty}\lim_{i\longrightarrow\infty}E_g\big(u;B_{R\delta_i}(z_i)\!-\!B_{\delta_i(\mu)}(z_i)\big)
=\mathfrak m\!-\!\mu<\hbar_{J,g}\,.$$
Thus, Corollary~\ref{CylEner_crl} applies with $(R,T)$ replaced by 
$(\frac12\ln(R\delta_i/\delta_i(\mu)),\ln R)$
and $u$ replaced by the $J$-holomorphic~map
$$v\!:  (-R,R)\!\times\!S^1\longrightarrow X,\qquad
v\big(r,\textnormal{e}^{\mathfrak i\theta}\big)=u\big(z_i\!+\!\sqrt{R\delta_i\delta_i(\mu)}\,\textnormal{e}^{r+\mathfrak i\theta}\big).$$
By the first statement of Corollary~\ref{CylEner_crl},
$$E_g\big(u;B_{\delta_i}(z_i)\big)-E_g\big(u;B_{R\delta_i(\mu)}(z_i)\big)=
E_g\big(u;B_{\delta_i}(z_i)\!-\!B_{R\delta_i(\mu)}(z_i)\big)\le \frac{C_{J,g}}{R}E_g(u)$$
for all $i$ sufficiently large (depending on~$R$);
see Figure~\ref{CylEner_fig}.
Combining this with (\ref{noLoss_e3}), we obtain~(\ref{noEloss_e1}).\\



